//#region src/shims/search-params-gate.ts
function createSearchParamsGate(options) {
	let resolve;
	const decided = new Promise((resolvePromise) => {
		resolve = resolvePromise;
	});
	const thenable = decided;
	thenable.status = "pending";
	const gate = {
		decision: null,
		decided
	};
	const decide = (decision) => {
		if (gate.decision !== null) return false;
		gate.decision = decision;
		thenable.status = "fulfilled";
		thenable.value = void 0;
		resolve();
		return true;
	};
	return {
		gate,
		open() {
			if (decide("real")) options.onOpen();
		},
		settle() {
			decide("bailout");
		}
	};
}
//#endregion
export { createSearchParamsGate };
